// Monte Carlo π: throw random darts at a square
let inside = 0;
const N = 1_000_000;
for (let i = 0; i < N; i++) {
  const x = Math.random(), y = Math.random();
  if (x * x + y * y <= 1) inside++;
}
console.log("π ≈", 4 * inside / N);

