\section*{RSA in five lines}
Pick primes $p, q$ and let $N = pq$.
Pick $e$ with $\gcd\big(e, (p-1)(q-1)\big) = 1$.
Let $d \equiv e^{-1} \pmod{(p-1)(q-1)}$.
\begin{align*}
  y &= x^{e} \bmod N  && \text{encrypt} \\
  x &= y^{d} \bmod N  && \text{decrypt}
\end{align*}

